import re

from mmar_carl import StepDescription


def step_by_step_prompting(table_str: str, current_task: str, prev_steps_history: str = ""):
    prev_steps_history_block = f"""Выполни следующую задачу: {current_task}"""
    if prev_steps_history != "":
        prev_steps_history_block = f"""
            История предыдущих шагов анализа:
            {prev_steps_history}

            Основываясь на результатах предыдущих шагов, выполни следующую задачу:
            {current_task}
        """

    return f"""Таблица с показателями:
{table_str}

{prev_steps_history_block}

ТРЕБОВАНИЯ К ОТВЕТУ:
1. **Объём — не менее 3 содержательных абзацев (≥ 250 слов)**. Не «один параграф»,
   не «кратко». Это шаг профессионального аналитического разбора, не подпись к графику.
2. **Первый абзац — констатация числа**: какие именно метрики/коэффициенты ты считал,
   их фактические значения за оба периода, абсолютное и процентное изменение, знак
   (рост/снижение). Округление до одной десятой для процентов, до миллиардов/миллионов
   для абсолютов — как в исходных данных.
3. **Второй абзац — объяснение причины**: ПОЧЕМУ показатель так изменился? Какие компоненты
   баланса/P&L/cash flow дали основной вклад в дельту? Связывай с метриками из истории
   предыдущих шагов, если они уже посчитаны. **ЗАПРЕТ на спекуляции:** если в таблице
   данных недостаточно для прямой атрибуции — НЕ выдвигай гипотез, не используй фразы
   «по всей видимости», «вероятно», «возможно», «скорее всего», «может быть». Вместо
   этого пиши коротко: «По имеющимся метрикам атрибуция причины невозможна — для
   корректной аттрибуции нужны данные о [конкретных недостающих метриках]» и переходи
   к выводу. Слабо обоснованные гипотезы хуже честного признания пробела в данных.
4. **Третий абзац — вывод и контекст**: позитивный это или негативный сигнал? Где банк/
   компания относительно отраслевой нормы (упомяни типичные диапазоны: NIM 2-6%, CIR
   40-55%, NPL 3-7%, ROE 10-15%, Net Debt/EBITDA 1.5-3.0× и т.п. — что применимо к
   данной метрике). Какую риск-импликацию это несёт для следующего периода.
5. Используй конкретные числа из таблицы — каждое утверждение должно опираться на
   цифру, а не на общие фразы вроде «компания сохраняет устойчивость».
6. Без формул в тексте, без markdown-таблиц. Цифры выписывай прямо в текст.
7. Не пересказывай задачу, не задавай уточняющих вопросов, не передавай инструкций.
"""




def pseudo_reasoning_step_to_prompt(step: StepDescription) -> str:
    return f"""Текущий шаг - это '{step.title}'. 
            Твоя цель звучит следующим образом: '{step.aim}'. 
            Главная задача: '{step.stage_action}'.
            Ответь на следующие вопросы: '{step.reasoning_questions}'
            Пример рассуждений, который делает эксперт в данной задаче - '{step.example_reasoning}'
            """


def executive_summary_prompt(full_report: str, metrics_table: str) -> str:
    """
    Создает промпт для генерации сжатой выжимки из полного отчета
    
    Args:
        full_report: Полный текст аналитического отчета
        metrics_table: Таблица с показателями (форматированная строка)
    
    Returns:
        Промпт для LLM
    """
    return f"""Ты — старший финансовый аналитик с 15+ лет опыта. Тебе предоставлен полный
пошаговый аналитический отчёт о финансовом состоянии компании и таблица с её показателями.

ТАБЛИЦА С ПОКАЗАТЕЛЯМИ:
{metrics_table}

ПОЛНЫЙ АНАЛИТИЧЕСКИЙ ОТЧЁТ:
{full_report}

ЗАДАЧА:
Подготовь развёрнутое итоговое аналитическое заключение «Ключевые выводы» для
инвестиционного комитета или кредитного риск-отдела банка. Это профессиональный
обзор, **не саммари** — объёмом не менее 1500 слов (~2 страницы A4).

СТРУКТУРА (минимум 9 разделов, каждый по 1-3 содержательных абзаца):

1. **Общая характеристика финансового состояния** — главный вывод периода одной
   ёмкой фразой плюс три ключевые цифры, его подтверждающие (например, чистая
   прибыль X млрд, ROE Y%, Stage 3 share Z%). Один абзац.

2. **Доходность и рентабельность** — динамика выручки/NII, маржа (gross/EBITDA/NIM в
   зависимости от типа компании), рентабельность (ROE/ROA). Не просто перечисли,
   а объясни ПОЧЕМУ растёт или падает каждый показатель. 2-3 абзаца.

3. **Качество активов и кредитный риск** — структура портфеля/запасов/дебиторки,
   доля проблемных активов (Stage 3 / NPL / просроченка), cost of risk, покрытие
   резервами. Если данных мало — объясни, какой сигнал это даёт. 2-3 абзаца.

4. **Финансовая устойчивость и структура капитала** — leverage (Net Debt/EBITDA или
   CET1/Tier1 ratio для банков), способность обслуживать долг, ликвидность. Сравни
   с типичными диапазонами для отрасли. 2-3 абзаца.

5. **Операционная эффективность** — Cost-to-Income Ratio (CIR), доля OPEX в
   выручке, динамика затрат на персонал. Что говорит об управленческой
   дисциплине. 1-2 абзаца.

6. **Главные позитивные факторы** — три пункта, по 2-3 предложения каждый, с
   конкретными цифрами в подтверждение.

7. **Главные риски** — три пункта, по 2-3 предложения каждый, с указанием
   масштаба риска (если можно его оценить количественно).

8. **Итоговая оценка** — общий вывод по кредитоспособности / инвест-привлекательности,
   с однозначной рекомендацией («устойчиво / умеренный риск / повышенный риск»).
   Один абзац.

9. **На что смотреть в следующем периоде** — 3-5 leading indicators, по которым
   можно судить о развитии ситуации (например: «темп роста Stage 2 → ранний
   индикатор миграции в Stage 3», «оборачиваемость дебиторки → ранний сигнал
   проблем со сбытом»). Один абзац.

ВАЖНЫЕ ПРАВИЛА:
- **НЕ упоминай показатели, которых НЕТ в таблице.** Если CET1 ratio не раскрыт —
  пиши «банк не раскрывает CET1 в обобщённой отчётности» вместо выдумывания цифры.
- **Каждое утверждение — с подтверждением числом** из таблицы. Запрещено: «компания
  устойчива». Разрешено: «капитал вырос на 110.4 млрд руб. до 1088.1 млрд, что
  отражает накопление прибыли при отсутствии дивидендов и взносы акционера на 25.5 млрд».
- **Сравнивай с предыдущим периодом везде, где есть данные**, и явно объясняй причину
  изменения (используя метрики из истории предыдущих шагов отчёта).
- Используй термины из соответствующего блока финансового анализа (для банков:
  NII, NIM, Stage 1/2/3, ECL, CET1, RWA, LDR, CIR, ROE, cost of funds, cost of risk;
  для нефинансовых компаний: EBITDA margin, FCF, CAPEX intensity, ROIC, working
  capital turnover, Net Debt/EBITDA, interest coverage).
- Без markdown-таблиц, без формул, без bullet-списков (нумерованные списки в
  разделах «Позитивы» / «Риски» — допустимы).
- Объём — **не менее 1500 слов** (это жёсткое требование, не пожелание).
- Не задавай уточняющих вопросов, не передавай инструкций пользователю.
"""


